mapper.select:
SELECT article_id as id, COUNT(*) AS repostCount
FROM user_repost
WHERE article_id IN

    #{articleId}

GROUP BY article_id;

select user_id, article_id, note, create_time
from user_repost
where
    user_id=#{userId}
  and (#{lastCreateTime} is null
    or create_time < #{lastCreateTime}
    or (create_time=#{lastCreateTime} and article_id < #{lastId}))
order by create_time desc , article_id desc
limit #{size}
